import{_ as o,o as a,c as d,a2 as i}from"./chunks/framework.CTeY_0bQ.js";const m=JSON.parse('{"title":"0007 一次安装，多库共用；库内只放专属配置","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0007-one-install-many-repos.md","filePath":"reference/adr/0007-one-install-many-repos.md","lastUpdated":null}'),c={name:"reference/adr/0007-one-install-many-repos.md"};function l(t,e,r,s,n,p){return a(),d("div",null,[...e[0]||(e[0]=[i('<div><h1 id="_0007-一次安装-多库共用-库内只放专属配置" tabindex="-1">0007 一次安装，多库共用；库内只放专属配置 <a class="header-anchor" href="#_0007-一次安装-多库共用-库内只放专属配置" aria-label="Permalink to &quot;0007 一次安装，多库共用；库内只放专属配置&quot;">​</a></h1><ul><li>状态：提议（待摸底实验 A、实验 5 确认平台上的可行性）；决定 1、4、5、6 的引擎部分已在 M2c 实现（见文末&quot;实现&quot;）</li><li>日期：2026-10-28</li><li>关联：<a href="./0003-generate-once-then-lock">ADR 0003</a>、<a href="./0004-external-contracts-stay-stable">ADR 0004</a>、<a href="./0006-deterministic-engine-platform-capabilities">ADR 0006</a></li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>laoshi 要服务多套代码库，<strong>不能每个代码库安装一次</strong>；代码库级专属配置除外。</p><p>试用平台（摸高）的约束：</p><ul><li>沙箱只挂载使用者的工作区 <code>/data/workspace</code>（默认 4 GB，可扩容），工作区外的目录在下一次对话会被清理。<code>$HOME</code> 和 npm 全局目录不能当作持久位置。</li><li>工作区的 <code>repos/</code> 下同时放前端和多个后端微服务，一个需求经常涉及其中几个。</li><li>平台有<strong>个人版和团队版</strong>，使用方式基本一致，区别只是单人使用还是多人共用；团队版没有特殊的团队配置。</li></ul><p>现有设计默认&quot;机器级&quot;就是 <code>~/.laoshi/</code> 加 npm 全局安装，在该平台上每次对话都会丢失。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ol><li><p><strong>安装单位是&quot;安装根&quot;，不是代码库。</strong> 安装根由 <code>LAOSHI_HOME</code> 指定，本机默认 <code>~/.laoshi/</code>。laoshi 本体、skill、适配器与锁定文件、安装级配置、使用记录与索引都在安装根内。一个安装根服务所有代码库，代码库里不安装任何东西。</p></li><li><p><strong>安装根必须在持久位置。</strong> 在摸高平台上放在工作区内（建议 <code>/data/workspace/.laoshi/</code>），本体用 <code>npm install --prefix &lt;安装根&gt;</code> 安装，不依赖 npm 全局目录和 <code>$HOME</code>。平台从哪里加载 skill 由适配器负责：能指向安装根时直接指向；不能时由适配器在会话开始时从安装根恢复。代码库内不放 skill 副本。</p></li><li><p><strong>代码库内只放专属配置和需求产出：</strong></p><ul><li><code>.laoshi.json</code>、<code>.laoshi/</code>（<code>project-notes.md</code>、<code>verify.md</code> 等）；</li><li>平台要求放在代码库内的工作区配置（例如 Paseo 的 <code>paseo.json</code>），由对应适配器的文档写明；</li><li>需求产出 <code>docs/features/&lt;需求&gt;/</code>（含 <code>.pipeline/state.json</code>）。</li></ul><p><code>laoshi-setup</code> 不向代码库复制 skill、提示词、脚本或引擎代码。req-kit 写进代码库的模板脚本（<code>with-port.mjs</code>、<code>copy-local-files.mjs</code>）改为适配器资产，由代码库配置引用。</p></li><li><p><strong>配置两层：安装级 → 代码库级</strong>，后者覆盖前者。不设团队层：团队版下安装级配置本身就是团队共享的。req-kit 1.x 的团队层配置继续读取，<code>laoshi migrate</code> 提示合并到安装级。</p></li><li><p><strong>个人版与团队版是同一套设计</strong>，个人版就是只有一个使用者的团队版。</p><ul><li>共享：本体、适配器与锁定文件、安装级配置。</li><li>按使用者区分：使用记录、通知对象、并发名额、需求发起人。使用者身份由适配器提供（平台环境变量等），取不到时用安装级配置里的名字或系统用户名。</li><li>凭据只来自使用者自己的环境变量，不写入安装根（团队版下安装根是共享的）。</li></ul></li><li><p><strong>每次运行都带代码库标识和使用者标识。</strong> 引擎从当前目录向上找 git 根确定代码库，标识为代码库根目录路径加远程地址。使用记录、通知事件、<code>laoshi api</code> 输出新增 <code>repo</code>、<code>user</code> 字段；按 ADR 0004 只加不改，仍为 <code>schema: 1</code>。</p></li><li><p><strong>一次升级会影响所有代码库，所以：</strong> 代码库配置可以声明最低版本（如 <code>&quot;laoshi&quot;: &quot;&gt;=1.2&quot;</code>），由 <code>doctor</code> 检查；升级前列出安装根下各代码库进行中的需求；读到旧版状态时迁移并保留 <code>.bak</code>。</p></li></ol><h2 id="不做" tabindex="-1">不做 <a class="header-anchor" href="#不做" aria-label="Permalink to &quot;不做&quot;">​</a></h2><ul><li>跨安装根的汇总与权限管理（多个团队各自一个安装根时的统一视图另行设计）。</li><li>代码库级安装 laoshi 的模式（例如作为代码库的 devDependency）。</li></ul><h2 id="待验证-见-platform-discovery-实验-a、实验-5" tabindex="-1">待验证（见 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/platform-discovery.md" target="_blank" rel="noreferrer">platform-discovery</a> 实验 A、实验 5） <a class="header-anchor" href="#待验证-见-platform-discovery-实验-a、实验-5" aria-label="Permalink to &quot;待验证（见 [platform-discovery](https://github.com/yiyisf/laoshi/blob/main/docs/design/platform-discovery.md) 实验 A、实验 5）&quot;">​</a></h2><ol><li>安装在工作区内的 laoshi，在下一次对话里能直接使用。</li><li>平台能否从工作区内的目录加载 skill。</li><li>团队版下成员是否共用同一个工作区、文件权限如何、能否在沙箱里取到当前使用者身份。</li><li>安装根占用的空间（含 <code>node_modules</code>）在 4 GB 配额内可接受。</li></ol><p>第 1、2 项任一为&quot;否&quot;，回到本 ADR 重新评估安装根的位置与 skill 的加载方式。</p><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>解决计划待定项 4：锁定文件放安装根。</li><li><a href="./../design/architecture">architecture</a> §5、§6，<a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/init-bootstrap.md" target="_blank" rel="noreferrer">init-bootstrap</a> §6，<a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/platform-discovery.md" target="_blank" rel="noreferrer">platform-discovery</a>，<a href="https://github.com/yiyisf/laoshi/blob/main/docs/extraction/plan.md" target="_blank" rel="noreferrer">plan</a> 随本 ADR 更新。</li><li>后续：<code>contracts/usage-record.md</code>、<code>notifier-event.md</code>、<code>cli-json.md</code> 新增 <code>repo</code>、<code>user</code> 字段；<code>contracts/state.md</code> 增加发起人；<a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/compat-migration.md" target="_blank" rel="noreferrer">compat-migration</a> 的路径对照改为以 <code>LAOSHI_HOME</code> 为准；<code>laoshi-setup</code> 按决定 3 改造。</li></ul><h2 id="实现-m2c-2026-11-02" tabindex="-1">实现（M2c，2026-11-02） <a class="header-anchor" href="#实现-m2c-2026-11-02" aria-label="Permalink to &quot;实现（M2c，2026-11-02）&quot;">​</a></h2><ul><li>决定 1：安装根由 <code>LAOSHI_HOME</code> 指定（<code>engine/src/locations.ts</code>），<code>REQ_KIT_HOME</code> 继续有效；都没有时为 <code>~/.laoshi</code>，机器上只有 req-kit 的 <code>~/.req-kit</code> 时沿用它，直到迁移。<code>doctor</code> 显示安装根和它是怎么选出来的。</li><li>决定 4：代码库级配置为 <code>.laoshi.json</code>，只有旧名 <code>.requirement-pipeline.json</code> 时读旧名，两者都在时只读新名并在 <code>doctor</code> 中提示。<code>platform</code>、<code>user</code> 只能写在安装级配置中。团队配置（<code>teamConfig</code>）继续读取，<code>doctor</code> 提示合并到安装级。</li><li>各平台的设置放在 <code>platform.&lt;id&gt;</code>：Paseo 为 <code>platform.paseo.daemonUrl</code> / <code>daemonPasswordEnv</code>（顶层的旧写法继续有效），dsh 为 <code>platform.dsh.home</code>。</li><li>决定 5、6：<code>engine/src/identity.ts</code>。代码库标识为 <code>{ root, remote }</code>：需求自己的 worktree 归属原仓库，远程地址去掉凭据。使用者依次取 <code>LAOSHI_USER</code>、安装级配置的 <code>user</code>、系统用户名。使用记录（<code>user</code>、<code>requirement.codebase</code>）、通知事件（<code>codebase</code>、<code>user</code>）、<code>req api list</code>（<code>codebase</code>）只加字段，仍为 <code>schema: 1</code>。字段名与本 ADR 原写的 <code>repo</code> 不同：通知事件已有 <code>repo</code>（需求所在目录），所以改叫 <code>codebase</code>。</li><li>还没有做：使用者身份由适配器提供（两个适配器都还取不到平台上的使用者）；<code>.requirement-pipeline/</code> 目录改名为 <code>.laoshi/</code>（和 <code>/laoshi</code> 改名一起在 M2e 处理）；决定 7 的&quot;升级前列出各代码库进行中的需求&quot;（属于安装器，M7）。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/adr/0007-one-install-many-repos.md">docs/adr/0007-one-install-many-repos.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/docs/adr/0007-one-install-many-repos.md">在 GitHub 上编辑</a></p>',2)])])}const u=o(c,[["render",l]]);export{m as __pageData,u as default};
